import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { execFileSync } from "node:child_process";
const blob = ``;
const files = JSON.parse(zlib.decompress(Buffer.from(blob, "base64")).toString("utf8"));
const root = process.cwd();
for (const [rel, b64] of Object.entries(files)) {
  const out = path.join(root, rel);
  if (!out.startsWith(root + path.sep) && out !== root) throw new Error(`Unsafe path: ${rel}`);
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, Buffer.from(b64, "base64"));
}
execFileSync(process.platform === "win32" ? "npx.cmd" : "npx", ["next", "build"], { stdio: "inherit" });